import json, os, subprocess, sys, glob
W = "/kaggle/working"
open(W + "/_leg.py", "w").write('#!/usr/bin/env python3\n"""Our ensemble leg v2: N dense80 members, rank-mean per finding. Same studies, windows and precision as v1\n(ours_leg.py); the changes are throughput only: studies are built by DataLoader workers (v1 built them in the main\nprocess, one at a time) and every visible GPU scores whole studies with its own copy of all members (v1 used\ncuda:0 only). Both eval passes of a study go through a model in one forward.\nExtra env: OURS_ROOT (test root override, for benchmarks), OURS_LIMIT (first N studies), OURS_WORKERS (default: all\ncores), OURS_GPUS (default: all), OURS_FLIP=1 (the second eval pass sees the left-right mirrored study, as in training\n`_mirror`; default off).\n\nv1 docstring:\n\nGenerated by scripts/build_ensemble_kernel.py from submit-dense80-5bc0 (same preprocessing,\nsame model class, same eval windows). Each study is built ONCE and scored by every member.\nEnv: OURS_MEMBERS (json list of weight file names), OURS_OUT (csv path), OURS_DEADLINE\n(unix seconds; past it the leg aborts non-zero so the caller keeps the public output).\n\nGeometry matches our train cache (outputs/kernels/dense80_cache): 80 slots, span 2-98%,\n140 mm crop, 336 px. Model = CoAtNet-384 + per-finding attention head, imagenet norm,\nk_eval=24 with 2 phase-shifted eval passes (matches RunPod train defaults).\n\nWeights: girishbose/rsna-knee-rp-n-5bc0a0f45d75-out / raptor_ft_5bc0a0f45d75.pt\nInference pattern forked from dreaddevelopment/knee-mri-twelve-findings-from-a-single-model.\nInternet OFF.\n"""\nfrom __future__ import annotations\n\nimport copy\nimport gc\nimport glob\nimport os\nimport threading\nimport time\n\nos.environ.setdefault("HF_HUB_OFFLINE", "1")\nos.environ.setdefault("TRANSFORMERS_OFFLINE", "1")\nos.environ.setdefault("HF_HUB_DISABLE_TELEMETRY", "1")\n\nimport math\n\nimport numpy as np\nimport pandas as pd\nimport timm\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\ntorch.backends.cudnn.benchmark = True\ntorch.backends.cuda.matmul.allow_tf32 = True\n\n# ---- must match dense80 train cache + 5bc0 genome --------------------------------\nIMG = 336\nCROP_MM = 140.0\nSPAN_LO, SPAN_HI = 0.02, 0.98\nSLOTS = [("Sagittal", 1, 22), ("Sagittal", 0, 18), ("Coronal", 1, 15),\n         ("Coronal", 0, 10), ("Axial", -1, 15)]\nMAXS = sum(s[2] for s in SLOTS)  # 80\nSAG_SLOTS = 40  # slots below this are sagittal (train_knee.py)\nBLOCKS = [(0, 22), (22, 40), (40, 55), (55, 65), (65, 80)]   # sag fluid, sag other, cor fluid, cor other, axial\nK_EVAL = 24\nEVAL_PASSES = 2\nNORM = "imagenet"\nLAB = ["ACL", "MCL", "Medial Meniscus", "Lateral Meniscus", "Medial OA", "Lateral OA",\n       "PF OA", "Effusion", "Synovitis", "Baker\'s", "Contusion", "Fracture"]\n_MEAN = torch.tensor([0.485, 0.456, 0.406]).view(3, 1, 1)\n_STD = torch.tensor([0.229, 0.224, 0.225]).view(3, 1, 1)\nMEMBERS = []  # filled from OURS_MEMBERS\nARCH_DEFAULT = "coatnet_rmlp_2_rw_384.sw_in12k_ft_in1k"\nRES_DEFAULT = 384\n\n\ndef build_backbone(arch, pretrained=False):\n    hybrid = arch.startswith(("maxvit", "maxxvit", "coatnet", "coat_", "convnext"))\n    is_vit = (not hybrid) and any(k in arch for k in ("vit", "deit", "dinov2", "eva", "beit"))\n    kw = dict(pretrained=pretrained, num_classes=0, in_chans=3)\n    if is_vit:\n        kw.update(global_pool="token", dynamic_img_size=True)\n    else:\n        kw.update(global_pool="avg")\n    return timm.create_model(arch, **kw)\n\n\nclass RaptorClassifier(nn.Module):\n    def __init__(self, backbone, F_dim=768, n=12, drop=0.2):\n        super().__init__()\n        self.backbone = backbone\n        self.norm = nn.LayerNorm(F_dim)\n        self.att = nn.Sequential(nn.Linear(F_dim, 256), nn.Tanh(), nn.Dropout(drop),\n                                 nn.Linear(256, n))\n        self.clsW = nn.Parameter(torch.zeros(n, F_dim))\n        self.clsb = nn.Parameter(torch.zeros(n))\n        nn.init.trunc_normal_(self.clsW, std=0.02)\n        self.n = n\n\n    def encode(self, x):\n        B, K = x.shape[:2]\n        f = self.backbone(x.flatten(0, 1))\n        return f.view(B, K, -1)\n\n    def head(self, feats):\n        h = self.norm(feats)\n        a = torch.softmax(self.att(h), dim=1)\n        pooled = torch.einsum("bkn,bkf->bnf", a, h)\n        return (pooled * self.clsW).sum(-1) + self.clsb\n\n    def forward(self, x, pos=None):\n        return self.head(self.encode(x))\n\n\ndef _fourier(rel):\n    f = rel[..., None] * (math.pi * (2.0 ** torch.arange(6, device=rel.device, dtype=rel.dtype)))\n    return torch.cat([torch.sin(f), torch.cos(f)], -1)\n\n\nclass SeqClassifier(nn.Module):\n    """train_knee.SeqClassifier (slot-aware head): same modules, same forward."""\n    def __init__(self, backbone, F_dim=384, n=12, drop=0.2, use_tr=True, use_sp=False, D=384, layers=2, heads=6):\n        super().__init__()\n        self.backbone = backbone\n        self.norm = nn.LayerNorm(F_dim)\n        self.att = nn.Sequential(nn.Linear(F_dim, 256), nn.Tanh(), nn.Dropout(drop),\n                                 nn.Linear(256, n))\n        self.clsW = nn.Parameter(torch.zeros(n, F_dim))\n        self.clsb = nn.Parameter(torch.zeros(n))\n        self.n, self.use_tr, self.use_sp = n, bool(use_tr), bool(use_sp)\n        self.blk_att = nn.Embedding(len(BLOCKS), F_dim)\n        self.pos_att = nn.Linear(12, F_dim)\n        if self.use_tr:\n            self.proj_in = nn.Linear(F_dim, D)\n            self.blk_tr = nn.Embedding(len(BLOCKS), D)\n            self.pos_tr = nn.Linear(12, D)\n            layer = nn.TransformerEncoderLayer(D, heads, 2 * D, dropout=0.1, batch_first=True, norm_first=True)\n            self.tr = nn.TransformerEncoder(layer, layers, enable_nested_tensor=False)\n            self.proj_out = nn.Linear(D, F_dim)\n            self.gamma = nn.Parameter(torch.zeros(1))\n        if self.use_sp:\n            self.sp_norm = nn.LayerNorm(F_dim)\n            self.sp = nn.Linear(F_dim, n)\n\n    def forward(self, x, pos=None):\n        B, K = x.shape[:2]\n        if self.use_sp:\n            fm = self.backbone.forward_features(x.flatten(0, 1))\n            t = fm.flatten(2).transpose(1, 2)\n            s = torch.softmax(self.sp(self.sp_norm(t)).float(), dim=1).to(t.dtype)\n            g = torch.einsum("thn,thc->tnc", s, t)\n            f = self.backbone.forward_head(g.reshape(-1, g.shape[-1], 1, 1)).view(B, K, self.n, -1)\n        else:\n            f = self.backbone(x.flatten(0, 1)).view(B, K, 1, -1)\n        e_att = 0.0\n        if pos is not None:\n            blk, ff = pos[..., 0].long(), _fourier(pos[..., 1].float())\n            e_att = (self.blk_att(blk) + self.pos_att(ff))[:, :, None, :]\n            if self.use_tr:\n                z = self.proj_in(self.norm(f.mean(2))) + self.blk_tr(blk) + self.pos_tr(ff)\n                f = f + self.gamma * self.proj_out(self.tr(z))[:, :, None, :]\n        h = self.norm(f)\n        a = self.att(h + e_att)\n        a = torch.diagonal(a, dim1=2, dim2=3) if self.use_sp else a[:, :, 0]\n        a = torch.softmax(a.float(), dim=1).to(h.dtype)\n        pooled = torch.einsum("bkn,bknf->bnf", a, h.expand(-1, -1, self.n, -1))\n        return (pooled * self.clsW).sum(-1) + self.clsb\n\n\ndef load_model(pt_path, device):\n    """-> (model, cfg); cfg = (res, sample, k_eval, canon) = the windows this member was trained and evaluated on\n    (canon: left knees are shown mirrored, train_knee --canon)."""\n    ck = torch.load(pt_path, map_location="cpu", weights_only=False)\n    arch = ck.get("arch", ARCH_DEFAULT)\n    res = int(ck.get("res", RES_DEFAULT))\n    head = ck.get("head", "mil")\n    bb = build_backbone(arch, pretrained=False)\n    if head == "mil":\n        model = RaptorClassifier(bb, F_dim=bb.num_features)\n    else:\n        model = SeqClassifier(bb, F_dim=bb.num_features, use_tr=head in ("seq", "seqtok"), use_sp=head in ("tok", "seqtok"))\n    model.load_state_dict(ck["model"], strict=True)\n    model.eval().to(device)\n    cfg = (res, ck.get("sample", "rand"), int(ck.get("k_eval", K_EVAL)), bool(ck.get("canon", False)))\n    del ck\n    gc.collect()\n    return model, cfg\n\n\ndef _eval_centers(mask, D, k, phase=0.0):\n    valid = np.where(mask > 0)[0]\n    if len(valid) < 3:\n        valid = np.arange(min(3, D))\n    lo, hi = int(valid.min()), int(valid.max())\n    cs = [c for c in range(lo + 1, hi) if c - 1 >= lo and c + 1 <= hi]\n    if not cs:\n        cs = [max(1, min((lo + hi) // 2, D - 2))]\n    frac = (np.linspace(0.0, 1.0, k) + float(phase)) % 1.0\n    idx = np.round(frac * (len(cs) - 1)).astype(int)\n    return [cs[i] for i in idx]\n\n\ndef _alloc(sizes, count):\n    tot = float(sum(sizes)) or 1.0\n    raw = [count * z / tot for z in sizes]\n    n = [int(r) for r in raw]\n    for i in sorted(range(len(sizes)), key=lambda i: raw[i] - n[i], reverse=True)[:count - sum(n)]:\n        n[i] += 1\n    for i in range(len(n)):\n        if n[i] == 0 and max(n) > 1:\n            n[n.index(max(n))] -= 1; n[i] = 1\n    return n\n\n\ndef _eval_centers_strat(mask, k, phase=0.0):\n    """train_knee.StudyWindows._centers_strat at eval: ordered windows from every filled series block."""\n    spans = []\n    for s, e in BLOCKS:\n        v = np.where(mask[s:e] > 0)[0]\n        if len(v) == 0:\n            continue\n        lo, hi = s + int(v.min()) + 1, s + int(v.max()) - 1\n        if hi < lo:\n            lo = hi = max(s + 1, min(s + int(v[len(v) // 2]), e - 2))\n        spans.append((lo, hi))\n    if not spans:\n        return [1] * k\n    cs = []\n    for (lo, hi), n in zip(spans, _alloc([hi - lo + 1 for lo, hi in spans], k)):\n        for j in range(n):\n            u = ((j + 0.5 + float(phase)) / n) % 1.0\n            cs.append(lo + int(round(u * (hi - lo))))\n    return cs\n\n\ndef _slot_pos(cs, D):\n    out = np.zeros((len(cs), 2), np.float32)\n    for i, c in enumerate(cs):\n        if D != 80:\n            out[i] = (0.0, c / max(D - 1, 1)); continue\n        for b, (s, e) in enumerate(BLOCKS):\n            if s <= c < e:\n                out[i] = (b, (c - s) / (e - s - 1.0)); break\n    return torch.from_numpy(out)\n\n\ndef eval_windows(vol, mask, k, res, phase=0.0, norm=NORM, flip=False, sample="rand"):\n    return eval_windows_pos(vol, mask, k, res, phase=phase, norm=norm, flip=flip, sample=sample)[0]\n\n\ndef eval_windows_pos(vol, mask, k, res, phase=0.0, norm=NORM, flip=False, sample="rand"):\n    """-> (x (K,3,res,res), pos (K,2) = series block and position inside it of every window)."""\n    D = vol.shape[0]\n    cs = _eval_centers_strat(mask, k, phase=phase) if sample == "strat" and D == 80 else _eval_centers(mask, D, k, phase=phase)\n    pos = _slot_pos([max(1, min(c, D - 2)) for c in cs], D)\n    wins = np.empty((len(cs), 3, res, res), np.float32)\n    for j, c in enumerate(cs):\n        c = max(1, min(c, D - 2))\n        tri = np.stack([vol[c - 1], vol[c], vol[c + 1]], 0).astype(np.float32) / 255.0\n        t = torch.from_numpy(tri)\n        if t.shape[-1] != res or t.shape[-2] != res:\n            t = F.interpolate(t[None], size=(res, res), mode="bilinear", align_corners=False)[0]\n        wins[j] = t.numpy()\n    x = torch.from_numpy(wins)\n    if flip:   # train_knee._mirror: sagittal windows reverse their slice (= channel) order, the others flip in-plane\n        for j, c in enumerate(cs):\n            x[j] = x[j].flip(0) if c < SAG_SLOTS else x[j].flip(-1)\n        sag = pos[:, 0] < 2\n        pos[sag, 1] = 1.0 - pos[sag, 1]\n    if norm == "imagenet":\n        x = (x - _MEAN) / _STD\n    return x, pos\n\n\n@torch.no_grad()\ndef infer_probs(model, x, device, pos=None):\n    """x: (P,K,3,res,res) already on `device`, one row per eval pass -> (12,) mean probability over the passes."""\n    if str(device).startswith("cuda"):\n        try:\n            with torch.autocast("cuda", dtype=torch.float16):\n                o = torch.sigmoid(model(x, pos).float())\n            return o.mean(0).cpu().numpy()\n        except RuntimeError:\n            torch.cuda.empty_cache()\n            return torch.sigmoid(model(x, pos).float()).mean(0).cpu().numpy()\n    return torch.sigmoid(model(x, pos).float()).mean(0).cpu().numpy()\n\n\ndef _make_reader():\n    import cv2\n    import pydicom\n    from pydicom.pixel_data_handlers.util import apply_modality_lut\n\n    def order_and_meta(sdir, geo=None):\n        """geo (optional dict) receives the series\' left-right position: \'cx\' = x of the stack centre in patient\n        coordinates (mm, + = patient left; same formula as outputs/kernels/geom-dump) and \'tag\' = Laterality."""\n        fs = glob.glob(sdir + "/*.dcm")\n        recs, ps_list = [], []\n        xs, half, tag = [], None, ""\n        for f in fs:\n            try:\n                h = pydicom.dcmread(f, stop_before_pixels=True)\n                iop = getattr(h, "ImageOrientationPatient", None)\n                ipp = getattr(h, "ImagePositionPatient", None)\n                if iop is not None and ipp is not None and len(iop) == 6:\n                    r = np.array(iop[:3], float)\n                    c = np.array(iop[3:], float)\n                    n = np.cross(r, c)\n                    pos = float(np.dot(np.array(ipp, float), n))\n                else:\n                    pos = float(getattr(h, "InstanceNumber", 0) or 0)\n                ps = getattr(h, "PixelSpacing", None)\n                if geo is not None:\n                    try:\n                        if iop is not None and ipp is not None and len(iop) == 6 and len(ipp) == 3:\n                            xs.append(float(ipp[0]))\n                            if half is None:\n                                half = (0.5 * int(getattr(h, "Columns", 0) or 0) * (float(ps[1]) if ps is not None else 0.5) * float(iop[0])\n                                        + 0.5 * int(getattr(h, "Rows", 0) or 0) * (float(ps[0]) if ps is not None else 0.5) * float(iop[3]))\n                        if not tag:\n                            tag = (str(getattr(h, "Laterality", "") or "").strip() or str(getattr(h, "ImageLaterality", "") or "").strip())[:1].upper()\n                    except Exception:\n                        pass\n                ps = float(ps[0]) if ps is not None else 0.5\n                ps_list.append(ps)\n                recs.append((pos, f, ps))\n            except Exception:\n                recs.append((0.0, f, 0.5))\n        recs.sort(key=lambda x: x[0])\n        med_ps = float(np.median(ps_list)) if ps_list else 0.5\n        if geo is not None:\n            geo["cx"] = (float(np.mean(xs)) + half) if xs and half is not None else None\n            geo["tag"] = tag\n        return [(f, ps) for _, f, ps in recs], med_ps\n\n    def read_px(f):\n        d = pydicom.dcmread(f)\n        a = apply_modality_lut(d.pixel_array, d).astype(np.float32)\n        if str(getattr(d, "PhotometricInterpretation", "")) == "MONOCHROME1":\n            a = a.max() - a\n        return a\n\n    def mm_crop_resize(a, ps):\n        h, w = a.shape\n        cpx = int(round(CROP_MM / max(ps, 1e-3)))\n        cpx = min(cpx, min(h, w))\n        y0 = (h - cpx) // 2\n        x0 = (w - cpx) // 2\n        a = a[y0:y0 + cpx, x0:x0 + cpx]\n        return cv2.resize(a, (IMG, IMG), interpolation=cv2.INTER_AREA)\n\n    return order_and_meta, read_px, mm_crop_resize\n\n\ndef _pick_series_for_slot(rows, plane, fluid, used):\n    cands = [r for r in rows if r["Anatomical_Plane"] == plane and r["SeriesInstanceUID"] not in used]\n    if fluid in (0, 1):\n        pref = [r for r in cands if int(r.get("Fluid_Sensitive", 0) or 0) == fluid]\n        if pref:\n            return pref[0]\n    return cands[0] if cands else None\n\n\ndef knee_is_left(cxs, tags):\n    """Side of the knee as the images show it (rule of agent/protocol/knee_sides.json): the sign of the stack centre\'s\n    x; within 5 mm of the midline the Laterality tag decides if there is one."""\n    cx = float(np.median(cxs)) if cxs else 0.0\n    tag = next((t for t in tags if t in ("L", "R")), None)\n    if abs(cx) > 5 or tag is None:\n        return cx > 0\n    return tag == "L"\n\n\ndef build_study(sid, ser_records, tsdir, reader, with_side=False):\n    order_and_meta, read_px, mm_crop_resize = reader\n    rows = ser_records.get(sid, [])\n    vol = np.zeros((MAXS, IMG, IMG), np.uint8)\n    idx = 0\n    used = set()\n    cxs, tags = [], []\n    for plane, fluid, k in SLOTS:\n        r = _pick_series_for_slot(rows, plane, fluid, used)\n        if r is None:\n            idx += k\n            continue\n        used.add(r["SeriesInstanceUID"])\n        geo = {}\n        files, med_ps = order_and_meta(f"{tsdir}/{sid}/{r[\'SeriesInstanceUID\']}", geo)\n        if geo.get("cx") is not None:\n            cxs.append(geo["cx"])\n        tags.append(geo.get("tag", ""))\n        if not files:\n            idx += k\n            continue\n        n = len(files)\n        lo, hi = int(n * SPAN_LO), int(n * SPAN_HI) - 1\n        hi = max(hi, lo)\n        picks = np.linspace(lo, hi, k).round().astype(int) if n > 1 else [0] * k\n        arrs, pss = [], []\n        for p in picks:\n            fp, ps = files[min(int(p), n - 1)]\n            try:\n                arrs.append(read_px(fp))\n                pss.append(ps)\n            except Exception:\n                arrs.append(None)\n                pss.append(med_ps)\n        valid = [a for a in arrs if a is not None]\n        if valid:\n            allpx = np.concatenate([a.ravel() for a in valid])\n            loq, hiq = np.percentile(allpx, [2.0, 98.0])\n        else:\n            loq, hiq = 0.0, 1.0\n        for a, ps in zip(arrs, pss):\n            if idx >= MAXS:\n                break\n            if a is None:\n                idx += 1\n                continue\n            aw = np.clip((a - loq) / (hiq - loq + 1e-6), 0, 1)\n            aw = mm_crop_resize(aw, ps if ps > 0 else med_ps)\n            vol[idx] = (aw * 255).astype(np.uint8)\n            idx += 1\n        if idx >= MAXS:\n            break\n    mask = (vol.reshape(MAXS, -1).sum(1) > 0).astype(np.uint8)\n    if with_side:\n        return vol, mask, knee_is_left(cxs, tags)\n    return vol, mask\n\n\ndef find_test_root():\n    for b in ("/kaggle/input/competitions/rsna-knee-abnormality-detection",\n              "/kaggle/input/rsna-knee-abnormality-detection"):\n        if os.path.exists(b + "/test.csv"):\n            return b\n    for d, _, f in os.walk("/kaggle/input"):\n        if "test.csv" in f and (os.path.isdir(d + "/test_series") or os.path.isdir(d + "/test_images")):\n            return d\n    for d, _, f in os.walk("/kaggle/input"):\n        if "test.csv" in f:\n            return d\n    raise RuntimeError("no test root under /kaggle/input")\n\n\ndef find_weight_file(fname):\n    for d in sorted(glob.glob("/kaggle/input/*/")):\n        if "competition" in d.lower():\n            continue\n        hits = glob.glob(os.path.join(d, "**", fname), recursive=True)\n        if hits:\n            return hits[0]\n    raise RuntimeError(f"{fname} not found under /kaggle/input")\n\n\n\nclass _Studies(torch.utils.data.Dataset):\n    """One item = one built study (80 x 336 x 336 uint8 + slot mask). Runs inside DataLoader workers."""\n\n    def __init__(self, ids, ser, tsdir):\n        self.ids, self.ser, self.tsdir, self._reader = ids, ser, tsdir, None\n\n    def __len__(self):\n        return len(self.ids)\n\n    def __getitem__(self, i):\n        t = time.time()\n        try:\n            if self._reader is None:\n                import cv2\n                cv2.setNumThreads(1)\n                self._reader = _make_reader()\n            vol, mask, left = build_study(self.ids[i], self.ser, self.tsdir, self._reader, with_side=True)\n            return i, vol, mask, time.time() - t, "", left\n        except Exception as e:\n            return i, None, None, time.time() - t, f"{type(e).__name__}: {e}", False\n\n\ndef _ident(x):\n    return x\n\n\ndef main():\n    import json\n    import sys\n    t0 = time.time()\n    members = json.loads(os.environ["OURS_MEMBERS"])\n    out = os.environ.get("OURS_OUT", "/kaggle/working/submission.csv")\n    deadline = float(os.environ.get("OURS_DEADLINE", "inf"))\n    flip = os.environ.get("OURS_FLIP", "0") == "1"\n    n_gpu = torch.cuda.device_count() if torch.cuda.is_available() else 0\n    n_gpu = min(n_gpu, int(os.environ.get("OURS_GPUS", n_gpu)))\n    devs = [f"cuda:{g}" for g in range(n_gpu)] or ["cpu"]\n    if n_gpu:   # the notebook process above us may still hold memory: skip a GPU that is nearly full\n        free = [torch.cuda.mem_get_info(g)[0] / 2 ** 30 for g in range(n_gpu)]\n        need = float(os.environ.get("OURS_MIN_FREE_GB", "6"))\n        keep = [g for g in range(n_gpu) if free[g] >= need] or [int(np.argmax(free))]\n        devs = [f"cuda:{g}" for g in keep]\n        print("gpu free GB " + " ".join(f"{f:.1f}" for f in free) + f" | using {devs}", flush=True)\n    workers = int(os.environ.get("OURS_WORKERS", os.cpu_count() or 2))\n    print(f"ours leg v2 | {len(members)} members | slots={MAXS} k_eval={K_EVAL} passes={EVAL_PASSES} flip={flip} | "\n          f"devices {devs} | workers {workers}", flush=True)\n\n    ROOT = os.environ.get("OURS_ROOT") or find_test_root()\n    tsdir = ROOT + "/test_series"\n    if not os.path.isdir(tsdir):\n        tsdir = ROOT + "/test_images"\n    test = pd.read_csv(ROOT + "/test.csv")\n    test["StudyInstanceUID"] = test["StudyInstanceUID"].astype(str)\n    test_ids = test["StudyInstanceUID"].tolist()\n    if os.environ.get("OURS_LIMIT"):\n        test_ids = test_ids[:int(os.environ["OURS_LIMIT"])]\n    tser = pd.read_csv(ROOT + "/test_series.csv")\n    tser["StudyInstanceUID"] = tser["StudyInstanceUID"].astype(str)\n    tser["SeriesInstanceUID"] = tser["SeriesInstanceUID"].astype(str)\n    SER = {k: v.to_dict("records") for k, v in tser.groupby("StudyInstanceUID")}\n\n    # Workers start building studies before the models load (they never touch CUDA).\n    torch.set_num_threads(1)\n    studies = _Studies(test_ids, SER, tsdir)\n\n    def loader(indices, n_workers):\n        ds = studies if indices is None else torch.utils.data.Subset(studies, indices)\n        return iter(torch.utils.data.DataLoader(\n            ds, batch_size=None, shuffle=False, num_workers=n_workers, collate_fn=_ident,\n            **(dict(prefetch_factor=2, persistent_workers=False) if n_workers else {})))\n\n    it = loader(None, workers)\n\n    per_dev = [[] for _ in devs]   # per device: [(model, (res, sample, k_eval, canon))] in member order\n    for fname in members:\n        wp = find_weight_file(fname)\n        m, cfg = load_model(wp, devs[0])\n        per_dev[0].append((m, cfg))\n        for g in range(1, len(devs)):\n            per_dev[g].append((copy.deepcopy(m).to(devs[g]).eval(), cfg))\n        print(f"loaded {wp} | res {cfg[0]} | {type(m).__name__} {cfg[1]} k{cfg[2]}{\' canon\' if cfg[3] else \'\'} | {time.time() - t0:.0f}s", flush=True)\n\n    N, M = len(test_ids), len(members)\n    probs = np.full((M, N, len(LAB)), np.nan, np.float32)\n    seen = np.zeros(N, bool)\n    passes = [(i / EVAL_PASSES, flip and i % 2 == 1) for i in range(EVAL_PASSES)] if EVAL_PASSES > 1 else [(0.0, False)]\n    it_lock, st_lock = threading.Lock(), threading.Lock()\n    st = {"done": 0, "fails": 0, "stop": None, "loader_err": None, "build": 0.0, "wait": 0.0,\n          "infer": np.zeros(M), "t_loop": time.time(), "left": 0}\n\n    def score(g, it):\n        dev = devs[g]\n        while st["stop"] is None and st["loader_err"] is None:\n            if time.time() > deadline:\n                st["stop"] = f"DEADLINE hit after {st[\'done\']}/{N} studies"\n                return\n            tw = time.time()\n            with it_lock:\n                try:\n                    i, vol, mask, tb, err, left = next(it)\n                except StopIteration:\n                    return\n                except Exception as e:   # a dead worker: the caller finishes the rest without workers\n                    st["loader_err"] = f"{type(e).__name__}: {e}"\n                    return\n            tw = time.time() - tw\n            ti = np.zeros(M)\n            try:\n                if vol is None:\n                    raise RuntimeError(err)\n                xs = {}\n                for j, (model, cfg) in enumerate(per_dev[g]):\n                    if cfg not in xs:   # members that share resolution and window plan share the tensors\n                        res, sample, k_eval, canon = cfg   # canon members see a left knee mirrored (= as a right knee)\n                        wp_ = [eval_windows_pos(vol, mask, k=k_eval, res=res, phase=ph, norm=NORM,\n                                                flip=fl != (canon and bool(left)), sample=sample)\n                               for ph, fl in passes]\n                        xs[cfg] = (torch.stack([w[0] for w in wp_]).to(dev), torch.stack([w[1] for w in wp_]).to(dev))\n                    tj = time.time()\n                    probs[j, i] = infer_probs(model, xs[cfg][0], dev, xs[cfg][1])\n                    ti[j] = time.time() - tj\n                del xs, vol, mask\n                bad = False\n            except Exception as e:\n                bad = True\n                probs[:, i] = np.nan\n                print(f"  study {i} {test_ids[i][:16]} FALLBACK ({type(e).__name__}: {e})", flush=True)\n            with st_lock:\n                seen[i] = True\n                st["done"] += 1\n                st["fails"] += bad\n                st["left"] += bool(left)\n                st["build"] += tb\n                st["wait"] += tw\n                st["infer"] += ti\n                if st["done"] % 50 == 0 or st["done"] == N:\n                    print(f"  {st[\'done\']}/{N} | {time.time() - t0:.0f}s", flush=True)\n\n    def run(it):\n        threads = [threading.Thread(target=score, args=(g, it), daemon=True) for g in range(len(devs))]\n        for t in threads:\n            t.start()\n        for t in threads:\n            t.join()\n\n    run(it)\n    if st["loader_err"] and st["stop"] is None:\n        todo = [int(i) for i in np.where(~seen)[0]]\n        print(f"loader failed ({st[\'loader_err\']}); building the remaining {len(todo)} studies in-process", flush=True)\n        st["loader_err"] = None\n        run(loader(todo, 0))\n    fails = st["fails"]\n    if st["stop"]:\n        print(st["stop"] + "; aborting leg", flush=True)\n        os._exit(3)\n    if st["loader_err"] or not seen.all():\n        print(f"only {int(seen.sum())}/{N} studies scored ({st[\'loader_err\']}); aborting leg", flush=True)\n        os._exit(5)\n    if N > 10 and fails > 0.05 * N:\n        print(f"too many fallbacks ({fails}/{N}); aborting leg", flush=True)\n        os._exit(4)\n    wall = time.time() - st["t_loop"]\n    print(f"knee side from the headers: left {st[\'left\']} | right {N - st[\'left\']}", flush=True)\n    print(f"timing | wall {wall / max(N, 1):.2f} s/study | build {st[\'build\'] / max(N, 1):.2f} cpu-s/study | "\n          f"loader wait {st[\'wait\'] / max(N, 1):.2f} | infer {st[\'infer\'].sum() / max(N, 1):.2f} gpu-s/study = "\n          + " ".join(f"{v / max(N, 1):.2f}" for v in st["infer"]), flush=True)\n\n    # Rank-mean across members (macro AUC reads only order); failed studies get the median rank.\n    df_rank = []\n    for j in range(M):\n        pj = pd.DataFrame(probs[j], columns=LAB)\n        df_rank.append(pj.rank(pct=True).fillna(0.5).to_numpy())\n    # Per-member ranks too: the blend may use a member subset per finding (specialist tails).\n    for j in range(M):\n        pm = pd.DataFrame(df_rank[j].astype(np.float32), columns=LAB)\n        pm.insert(0, "StudyInstanceUID", test_ids)\n        pm.to_csv(out[:-4] + f"_m{j}.csv", index=False)\n    final = np.mean(df_rank, axis=0).astype(np.float32)\n    sub = pd.DataFrame(final, columns=LAB)\n    sub.insert(0, "StudyInstanceUID", test_ids)\n    assert np.isfinite(sub[LAB].to_numpy()).all()\n    sub.to_csv(out, index=False)\n    print(f"wrote {out} | {sub.shape} | {time.time() - t0:.0f}s", flush=True)\n\n\nif __name__ == "__main__":\n    main()\n')
env = dict(os.environ, OURS_MEMBERS=json.dumps(['raptor_ft_r8cnxs3360.pt', 'raptor_ft_r8cnxs3361.pt', 'raptor_ft_r8cnxs3362.pt', 'raptor_ft_r8cnxs3363.pt', 'raptor_ft_r4cnxs3360.pt', 'raptor_ft_r4cnxs3361.pt', 'raptor_ft_r4cnxs3362.pt', 'raptor_ft_r4cnxs3363.pt']), OURS_OUT=W + "/submission.csv")
rc = subprocess.call([sys.executable, W + "/_leg.py"], env=env)
